# Attendance Recovery Computation
attended = 42
total = 60
threshold = 75

if attended < 0 or total < 0 or attended > total:
    print("Invalid attendance data")
elif total == 0 and attended == 0:
    print("No classes recorded yet")
else:
    current = attended * 100 / total
    extra = 0
    while (attended + extra) * 100 / (total + extra) < threshold:
        extra += 1
    print("Current attendance:", round(current, 2), "%")
    if extra == 0:
        print("Already eligible.")
    else:
        print("Consecutive classes to attend:", extra)
    print("Attendance after those classes:",
          round((attended + extra) * 100 / (total + extra), 2), "%")

# Warehouse Inventory Reconciliation
records = [
    ("Keyboard", 50, 20, 35, 34, 50),
    ("Mouse", 80, 10, 40, 50, 60),
    ("Monitor", 25, 5, 12, 18, 20),
]

print("WAREHOUSE RECONCILIATION")
for name, opening, incoming, dispatched, actual, target in records:
    if min(opening, incoming, dispatched, actual, target) < 0:
        print(name, "- INVALID: negative quantity")
    elif dispatched > opening + incoming:
        print(name, "- INVALID: dispatch exceeds available stock")
    else:
        expected = opening + incoming - dispatched
        discrepancy = actual - expected
        replenishment = max(0, target - actual)
        if discrepancy == 0:
            status = "MATCH"
        elif discrepancy < 0:
            status = "SHORTAGE"
        else:
            status = "SURPLUS"
        print(name, "Expected:", expected, "Actual:", actual,
              "Difference:", discrepancy, status,
              "Replenish:", replenishment)

# Password Policy Validation Engine
passwords = ["Kusuma@2026", "abc123", "Strong!!!9A", "password#9A"]

for password in passwords:
    failures = []
    if len(password) < 8:
        failures.append("must contain at least 8 characters")

    upper = lower = digit = special = False
    for ch in password:
        if ch.isupper():
            upper = True
        if ch.islower():
            lower = True
        if ch.isdigit():
            digit = True
        if ch in "!@#$%&*":
            special = True

    if not upper:
        failures.append("needs an uppercase letter")
    if not lower:
        failures.append("needs a lowercase letter")
    if not digit:
        failures.append("needs a digit")
    if not special:
        failures.append("needs a special character from !@#$%&*")
    if "password" in password.lower():
        failures.append("contains prohibited word 'password'")

    repeated = False
    for i in range(len(password) - 2):
        if password[i] == password[i + 1] == password[i + 2]:
            repeated = True
    if repeated:
        failures.append("contains three identical consecutive characters")

    if len(failures) == 0:
        print(password, ": ACCEPTED")
    else:
        print(password, ": REJECTED")
        for failure in failures:
            print(" -", failure)

# Integrated Student Record Consistency Checker
records = [
    ("26000293", "Kusuma Priya", 92, 96, "CSE101"),
    ("26000294", "Yamuna", 78, 82, "CSE101"),
    ("26000293", "Duplicate Roll", 65, 75, "CSE102"),
    ("26000296", "", 108, 110, ""),
]

roll_numbers = []
for record in records:
    roll_numbers.append(record[0])

print("STUDENT RECORD AUDIT")
for roll, name, marks, attendance, course in records:
    errors = []
    if roll == "":
        errors.append("missing roll number")
    if roll_numbers.count(roll) > 1:
        errors.append("duplicate roll number")
    if name.strip() == "":
        errors.append("missing student name")
    if marks < 0 or marks > 100:
        errors.append("marks outside 0-100")
    if attendance < 0 or attendance > 100:
        errors.append("attendance outside 0-100")
    if course.strip() == "":
        errors.append("missing course code")

    if len(errors) == 0:
        print(roll, name, ": VALID")
    else:
        print(roll, name if name else "(no name)", ": INVALID")
        for error in errors:
            print(" -", error)
